from taf.ul.kpi_selector.operations.operation_prototype.operation_prototype import OperationPrototype


class SwRollback(OperationPrototype):
    def __init__(self, bts):
        super(SwRollback, self).__init__(bts)
        self.operation_details = {
            "Timeout": 0,
            "Operation": "SW rollback",
            "Start point": "SW rollback request",
            "End point": "moment of sending the last response after successfully rolling back the SW package",
            "Requirement": "OM_GEN_SFS_PERF_CAP.2813",
        }

    def get_kpi(self, operability):
        """
        Activates the previous active software version on the BTS. Rollback always requires a site reset to activate
        the previous software version.
        KPI: Max Duration of SW Rollback
        Requirement: OM_GEN_SFS_PERF_CAP.2813
        """

        self.operation_details["Timeout"] += 900 if operability else 540

        return self.operation_details
